@app.route('/login/redirect')
def login_redirect():
    next_url = request.args.get('next', '/dashboard')
    # After login processing...
    return redirect(next_url)

@app.route('/logout')
def logout():
    return_url = request.args.get('return_to', '/')
    session.clear()
    return redirect(return_url)
